corrected_code:
auditor_router = APIRouter(
    prefix="/auditing",
    dependencies=[Depends(require_internal_auditor)]
)

@auditor_router.get("/audit/expenses/{expense_id}")
def view_audited_expense(
    expense_id: int,
    auditor: AuditorUser = Depends(get_current_auditor),
    db: Session = Depends(get_db)
):
    expense = db.query(EmployeeExpense).filter(
        EmployeeExpense.id == expense_id,
        EmployeeExpense.division_id == auditor.assigned_division_id
    ).first()
    if not expense:
        raise HTTPException(status_code=404, detail="Expense record not found or outside assigned division")
    return expense
